partial class Editor {
    NumberField cloneDiameter,cloneHardness,cloneOpacity;
    Control cloneRow,cloneHardnessRow,cloneOpacityRow;
    Bitmap cloneSample;
    TextureBrush cloneBrush;
    readonly Dictionary<Point,Bitmap> cloneTiles=new Dictionary<Point,Bitmap>();
    bool clonePainting,cloneAligned,cloneWasDirty;
    PointF cloneSource,cloneOffset,cloneLast,cloneHover;
    Rectangle cloneBounds;
    void ChangeTextSize(){
        if(syncing||Active==null)return;if(Active.Kind!="Text"&&Active.Kind!="Balloon"&&Active.Kind!="Emoji"){ChangeStyle();return;}if(Active.Size==(float)fontSize.Value)return;if(strokeAdjusting&&(!textAdjusting||strokeTarget!=Active))FinishStrokeAdjustment();
        if(!strokeAdjusting){Push();strokeAdjusting=textAdjusting=true;strokeTarget=Active;StartDragPreview();}float previous=Active.Size;Active.Size=(float)fontSize.Value;quickTextSizing=true;try{GrowTextBox(Active,previous);}finally{quickTextSizing=false;}
        if(strokeTimer==null){strokeTimer=new Timer {Interval=140};strokeTimer.Tick+=delegate{FinishStrokeAdjustment();};Disposed+=delegate{strokeTimer.Dispose();};}strokeTimer.Stop();strokeTimer.Start();RefreshImage();
    }
    static string DuplicateLink(string old,Dictionary<string,string> ids){if(String.IsNullOrEmpty(old))return null;string value;if(!ids.TryGetValue(old,out value)){value=Guid.NewGuid().ToString("N");ids.Add(old,value);}return value;}
    void MoveLinkedSelection(float dx,float dy){var chosen=SelectedObjects();bool withImage=chosen.Count>1&&chosen.Any(mark=>mark.Kind=="Image");foreach(var mark in chosen){mark.Move(dx,dy);if(withImage&&mark.MagnifyLinked&&mark.SourceInitialized){mark.SourceX+=dx;mark.SourceY+=dy;}}}
    void LinkSelection(bool unlink){var chosen=SelectedObjects();if(chosen.Count<2&&!unlink)return;Push();string id=unlink?null:Guid.NewGuid().ToString("N");foreach(var mark in chosen)mark.LinkId=id;Selected.Clear();foreach(var mark in chosen)Selected.Add(mark);RefreshImage();}
    void AddLayerContextActions(ContextMenuStrip menu){var chosen=SelectedObjects();var link=menu.Items.Add("Link layers (move together)",null,delegate{LinkSelection(false);});link.Enabled=chosen.Count>1;var unlink=menu.Items.Add("Unlink layers",null,delegate{LinkSelection(true);});unlink.Enabled=chosen.Any(mark=>!String.IsNullOrEmpty(mark.LinkId));var flatten=menu.Items.Add("Flatten into one",null,delegate{Guard(FlattenSelection);});flatten.Enabled=chosen.Count>0;menu.Items.Add(new ToolStripSeparator());}
    void FlattenSelection(){
        var chosen=SelectedObjects();if(chosen.Count==0)return;if(chosen.All(mark=>new[]{"Grayscale","Blur","Pixelate","Magnify"}.Contains(mark.Kind)))throw new InvalidOperationException("Select the content layers along with the adjustment before flattening.");FinishStrokeAdjustment();var bounds=Rectangle.Empty;foreach(var mark in chosen.Where(mark=>mark.Visible))bounds=UnionBounds(bounds,Art.DrawingBounds(mark,Background.Size));if(bounds.IsEmpty)return;
        using(var rendered=new Bitmap(Background.Width,Background.Height,PixelFormat.Format32bppArgb)){foreach(var mark in chosen.Where(mark=>mark.Visible))Art.Draw(rendered,mark);using(var patch=rendered.Clone(bounds,PixelFormat.Format32bppArgb)){
            var combined=new Mark {Kind="Image",Name="Combined layer",X=bounds.X,Y=bounds.Y,W=bounds.Width,H=bounds.Height,Width=0,Image=Art.Bytes(patch),IsCaptureBase=chosen.Any(mark=>mark.IsCaptureBase)};Push();int top=Marks.FindLastIndex(mark=>chosen.Contains(mark));int index=Marks.Take(top+1).Count(mark=>!chosen.Contains(mark));foreach(var mark in chosen)Marks.Remove(mark);Marks.Insert(index,combined);Selected.Clear();Selected.Add(combined);Active=combined;RefreshImage();
        }}
    }
    void AddCloneInspector(){
        var size=Row();size.Controls.Add(Caption("Brush size · px",145));cloneDiameter=Number(1,300,32);cloneDiameter.AcceleratedWheel=true;size.Controls.Add(cloneDiameter);cloneRow=size;inspector.Controls.Add(size);
        var hardness=Row();hardness.Controls.Add(Caption("Hardness · %",145));cloneHardness=Number(0,100,100);hardness.Controls.Add(cloneHardness);cloneHardnessRow=hardness;inspector.Controls.Add(hardness);
        var opacity=Row();opacity.Controls.Add(Caption("Opacity · %",145));cloneOpacity=Number(0,100,100);opacity.Controls.Add(cloneOpacity);cloneOpacityRow=opacity;inspector.Controls.Add(opacity);
        foreach(var field in new[]{cloneDiameter,cloneHardness,cloneOpacity})field.ValueChanged+=delegate{View.Invalidate();};
        tips.SetToolTip(cloneHardness,"0% gives soft edges; 100% gives a crisp edge.");tips.SetToolTip(cloneOpacity,"How strongly each stroke applies the sampled pixels.");
        Disposed+=delegate{clonePainting=false;ClearCloneTiles();ClearCloneTip();if(cloneSample!=null){cloneSample.Dispose();cloneSample=null;}};
    }
    int UpdateCloneInspector(string kind){cloneRow.Visible=cloneHardnessRow.Visible=cloneOpacityRow.Visible=kind=="Clone stamp";if(kind=="Clone stamp")inspectorHint.Text="Alt+click to sample pixels. Drag to paint. Hardness softens the edge; opacity blends each stroke.";return kind=="Clone stamp"?141:0;}
    void ResetCloneSource(){FinishCloneStroke();ClearCloneTip();if(cloneSample!=null){cloneSample.Dispose();cloneSample=null;}cloneAligned=false;}
    bool HandleCloneDown(MouseEventArgs e,Keys modifiers){
        if(tool!="Clone stamp")return false;if(e.Button==MouseButtons.Right&&clonePainting){CancelCloneStroke();return true;}if(e.Button!=MouseButtons.Left)return false;var point=View.ImagePoint(e.Location);
        if((modifiers&Keys.Alt)!=0){ResetCloneSource();cloneSample=(Bitmap)Preview.Clone();cloneSource=point;cloneHover=point;View.Capture=false;View.Invalidate();UpdateStatus("Clone source selected. Drag to paint; Alt+click to sample again.");return true;}
        if(cloneSample==null){UpdateStatus("Alt+click a clean area first, then drag to clone it.");return true;}
        if(cloneOpacity.Value==0)return true;cloneStrokeHardness=(float)cloneHardness.Value/100;cloneStrokeOpacity=(float)cloneOpacity.Value/100;if(!cloneAligned){cloneOffset=new PointF((float)Math.Round(cloneSource.X-point.X),(float)Math.Round(cloneSource.Y-point.Y));cloneAligned=true;}cloneWasDirty=dirty;Push();var existing=Marks.FirstOrDefault(mark=>mark.IsCloneLayer);if(existing!=null){Marks.Remove(existing);Marks.Add(existing);existing.Visible=true;RefreshImage();}cloneBrush=new TextureBrush(cloneSample,WrapMode.Clamp);cloneBrush.TranslateTransform(-cloneOffset.X,-cloneOffset.Y);clonePainting=true;cloneBounds=Rectangle.Empty;cloneLast=point;View.Capture=true;PaintCloneDab(point);return true;
    }
    bool HandleCloneMove(MouseEventArgs e){if(tool!="Clone stamp"||panning)return false;var point=View.UnboundedPoint(e.Location);cloneHover=point;if(!clonePainting){View.Invalidate();return true;}PaintCloneSegment(cloneLast,point);cloneLast=point;return true;}
    void PaintCloneDab(PointF point){PaintCloneSegment(point,point);}
    void PaintCloneSegment(PointF from,PointF to){
        if(cloneStrokeHardness<1||cloneStrokeOpacity<1){PaintSoftCloneSegment(from,to);return;}float size=(float)cloneDiameter.Value;var valid=RectangleF.Intersect(new RectangleF(-cloneOffset.X,-cloneOffset.Y,cloneSample.Width,cloneSample.Height),new RectangleF(PointF.Empty,Background.Size));
        using(var path=new GraphicsPath()){
            if(from==to)path.AddEllipse(to.X-size/2,to.Y-size/2,size,size);
            else {path.AddLine(from,to);using(var pen=new Pen(Color.Black,size){StartCap=LineCap.Round,EndCap=LineCap.Round})path.Widen(pen);}
            var area=Rectangle.Intersect(Rectangle.Ceiling(Inflate(path.GetBounds(),1)),Rectangle.Ceiling(valid));if(area.Width<1||area.Height<1)return;
            Action<Graphics> paint=graphics=>{graphics.InterpolationMode=InterpolationMode.NearestNeighbor;graphics.PixelOffsetMode=PixelOffsetMode.Half;graphics.SmoothingMode=SmoothingMode.AntiAlias;graphics.SetClip(valid,CombineMode.Intersect);graphics.FillPath(cloneBrush,path);};using(var graphics=Graphics.FromImage(Preview))paint(graphics);
            for(int y=area.Top/256;y<=(area.Bottom-1)/256;y++)for(int x=area.Left/256;x<=(area.Right-1)/256;x++){var key=new Point(x,y);Bitmap tile;if(!cloneTiles.TryGetValue(key,out tile)){tile=new Bitmap(256,256,PixelFormat.Format32bppArgb);cloneTiles.Add(key,tile);}using(var graphics=Graphics.FromImage(tile)){graphics.TranslateTransform(-x*256,-y*256);paint(graphics);}}
            cloneBounds=UnionBounds(cloneBounds,area);View.InvalidateMarkupCache();InvalidateDragArea(area);
        }
    }
    void ClearCloneTiles(){ClearSoftCloneTiles();if(cloneBrush!=null){cloneBrush.Dispose();cloneBrush=null;}foreach(var tile in cloneTiles.Values)tile.Dispose();cloneTiles.Clear();cloneBounds=Rectangle.Empty;}
    void FinishCloneStroke(){
        if(!clonePainting)return;clonePainting=false;View.Capture=false;if(cloneBounds.IsEmpty){ClearCloneTiles();RestoreCloneUndo();return;}
        var existing=Marks.FirstOrDefault(mark=>mark.IsCloneLayer);var bounds=cloneBounds;if(existing!=null)bounds=UnionBounds(bounds,existing.Shadow?Art.DrawingBounds(existing,Background.Size):Rectangle.Intersect(Rectangle.Ceiling(existing.VisibleBounds),new Rectangle(Point.Empty,Background.Size)));
        using(var patch=new Bitmap(bounds.Width,bounds.Height,PixelFormat.Format32bppArgb)){
            if(existing!=null){var local=existing.Clone();local.Move(-bounds.X,-bounds.Y);Art.Draw(patch,local);}
            using(var graphics=Graphics.FromImage(patch))foreach(var tile in cloneTiles)graphics.DrawImageUnscaled(tile.Value,tile.Key.X*256-bounds.X,tile.Key.Y*256-bounds.Y);
            var mark=new Mark {Kind="Image",Name=existing==null?"Clone stamp":existing.Name,IsCloneLayer=true,LinkId=existing==null?null:existing.LinkId,X=bounds.X,Y=bounds.Y,W=bounds.Width,H=bounds.Height,Width=0,Image=Art.Bytes(patch)};
            if(existing!=null)Marks.Remove(existing);Marks.Add(mark);Active=null;Selected.Clear();
        }ClearCloneTiles();RefreshImage();TouchRecovery();SyncLayers();UpdateStatus();View.Invalidate();
    }

    void CancelCloneStroke(){if(!clonePainting)return;clonePainting=false;View.Capture=false;ClearCloneTiles();RestoreCloneUndo();}
    void RestoreCloneUndo(){if(undo.Count>0){var before=undo[undo.Count-1];undo.RemoveAt(undo.Count-1);Restore(before);}dirty=cloneWasDirty;UpdateStatus();}
    public void DrawCloneCursor(Graphics graphics){
        if(tool!="Clone stamp")return;float size=(float)cloneDiameter.Value;var circle=new RectangleF(cloneHover.X-size/2,cloneHover.Y-size/2,size,size);
        var source=cloneAligned?new PointF(cloneHover.X+cloneOffset.X,cloneHover.Y+cloneOffset.Y):new PointF(cloneHover.X+(float)Math.Round(cloneSource.X-cloneHover.X),cloneHover.Y+(float)Math.Round(cloneSource.Y-cloneHover.Y));
        if(cloneSample!=null&&!clonePainting)DrawCloneTip(graphics,circle,source);
        using(var pen=new Pen(Color.FromArgb(200,225,255),1/View.Zoom)){graphics.DrawEllipse(pen,circle);if(cloneSample!=null){float d=6/View.Zoom;graphics.DrawLine(pen,source.X-d,source.Y,source.X+d,source.Y);graphics.DrawLine(pen,source.X,source.Y-d,source.X,source.Y+d);}}
    }
