        Action<bool,string> check=delegate(bool ok,string label){if(!ok)throw new Exception(label);report.Add("PASS "+label);};LoadImageDocument(Blank(500,300),"Linked layers");var text=new Mark {Kind="Text",Text="Smooth text",X=40,Y=40,W=140,H=40,Size=22};Marks.Add(text);Active=text;Selected.Clear();Selected.Add(text);SyncStyle();RefreshImage();int count=undo.Count;for(int i=0;i<6;i++){fontSize.Value=24+i*4;PrepareDragFrame();}check(strokeAdjusting&&text.Size==44,"Text size uses the reactive adjustment preview");FinishStrokeAdjustment();check(undo.Count==count+1&&text.W>140,"Text size burst is one Undo step and finishes with fitted bounds");Undo();check(Marks.Last().Size==22,"Undo restores previous text size");Redo();
