        LoadImageDocument(Blank(400,200),"Clone test");using(var graphics=Graphics.FromImage(Background)){}var original=Marks[0];using(var source=Blank(400,200)){using(var graphics=Graphics.FromImage(source)){graphics.Clear(Color.White);graphics.FillRectangle(Brushes.Red,20,20,150,100);}original.Image=Art.Bytes(source);}RefreshImage();SetTool("Clone stamp");View.Zoom=1;var origin=View.Origin;Func<int,int,MouseEventArgs> mouse=(x,y)=>new MouseEventArgs(MouseButtons.Left,1,(int)origin.X+x,(int)origin.Y+y,0);HandleCloneDown(mouse(35,35),Keys.Alt);cloneDiameter.Value=12;cloneHover=new PointF(250,100);using(var overlay=(Bitmap)Preview.Clone()){using(var graphics=Graphics.FromImage(overlay))DrawCloneCursor(graphics);var tint=overlay.GetPixel(250,100);check(tint.R>240&&tint.G>100&&tint.G<220&&Preview.GetPixel(250,100).G==255,"Sample preview is translucent and does not alter image pixels");}HandleCloneDown(mouse(250,100),Keys.None);HandleCloneMove(mouse(290,100));check(!StableMarkupPreview,"Clone painting bypasses stale zoom caches");check(Preview.GetPixel(270,100).G<20,"Continuous clone drag paints every pixel along its path");check(cloneTiles.Count>=2,"Clone painting crosses working tile boundaries smoothly");FinishCloneStroke();check(Marks.Count==2&&Marks.Last().Name=="Clone stamp","Clone stroke creates a separate editable patch layer");using(var image=Art.Render(Background,Marks))check(image.GetPixel(260,100).R>240&&image.GetPixel(260,100).G<20&&image.GetPixel(35,35).R>240,"Clone samples source pixels without changing the source");HandleCloneDown(mouse(300,100),Keys.None);HandleCloneMove(mouse(310,100));FinishCloneStroke();check(Marks.Count==2&&Marks.Last().IsCloneLayer,"Multiple clone strokes share one layer");Undo();check(Marks.Count==2,"Undo removes only the most recent clone stroke");Redo();check(Marks.Count==2,"Redo retains one clone layer");Undo();Undo();check(Marks.Count==1,"Clone stroke supports Undo");HandleCloneDown(mouse(320,150),Keys.None);CancelCloneStroke();check(Marks.Count==1&&!clonePainting&&cloneTiles.Count==0,"Cancelling a clone stroke discards its temporary tiles");ResetCloneSource();LoadImageDocument(Blank(3840,2160),"Clone performance");SetTool("Clone stamp");View.Zoom=1;origin=View.Origin;HandleCloneDown(mouse(80,80),Keys.Alt);cloneDiameter.Value=32;HandleCloneDown(mouse(700,700),Keys.None);var brush=cloneBrush;var liveBuffer=Preview;var clock=System.Diagnostics.Stopwatch.StartNew();for(int i=0;i<100;i++)HandleCloneMove(mouse(700+i*8,700+i*2));clock.Stop();check(Object.ReferenceEquals(brush,cloneBrush)&&Object.ReferenceEquals(liveBuffer,Preview),"4K clone painting reuses its source brush and preview buffer");File.WriteAllText(Path.Combine(folder,"clone-benchmark.txt"),"4K continuous clone drag: "+(clock.Elapsed.TotalMilliseconds/100).ToString("F2")+" ms per move (100 moves)." );CancelCloneStroke();ResetCloneSource();SetTool("Spotlight");Show();Application.DoEvents();UpdateInspector();check(!shadowToggleRow.Visible,"Spotlight has no drop shadow toggle");Hide();
        VerifyCloneBrush(report,folder);
